from pathlib import Path
import subprocess,json,shutil
r=Path.cwd()
def git(*a):return subprocess.check_output(['git',*a],text=True).strip()
audit=json.loads((r/'build/publication-audit111.json').read_text(encoding='utf8'));assert audit['passed'] and audit['remoteFetched']
release=git('rev-parse','readme-111^{commit}');assert release==audit['commit']==git('rev-parse','HEAD');tag=git('rev-parse','readme-111')
analysis=json.loads((r/'build/analysis111.json').read_text(encoding='utf8'));assert analysis['passed']
data={'edition':111,'releaseCommit':release,'annotatedTag':'readme-111','tagObject':tag,'audit':audit,'analysis':analysis,'releaseCI':json.loads((r/'build/ci111-release.json').read_text(encoding='utf8')),'scope':'Actual non-force main/edition111/tag push, fetched and audited. Exact completed data workflow archival, preserved source/outcome checks, explicit runtime transition, fresh reuse and recovery. Completed owned child goals archived under unchanged active64 capacity; CI separate.'}
(r/'docs/PUBLICATION_111.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf8')
folder=r/'docs/publication111';folder.mkdir(exist_ok=True)
names=['ci111-release.json','publication-audit111.json','push111.log','release111.log','release111.py','audit-publication111.py','publication111.py','finish-publication111.py','freeze111.py','check-guide111.cjs','visual111.json','visual-review111.json','documentation-check.json','doc-check111.log','guide111.log','guide111-1440.png','guide111-390.png','ci111-parent.json','analysis111.json','compile111.log','java111-archive.log','java111.log','java111-final.log','correction111.json','coverage111.json','java111-initial.log','archive111.log','archive111-native.log','archive111-final.log','native-boundary111.json','recorder-boundary111.json','inspect111.log','inspect111-initial.log','inspector-correction111.json','desktop111.log','desktop111-additional.log','source-identity111.json']
for name in names:assert (r/'build'/name).is_file(),name;shutil.copyfile(r/'build'/name,folder/name)
notice=f"Published release {release}; annotated readme-111 tag object {tag}. Actual main/edition111/tag push fetched and verified: {audit['canonicalSourceFiles']} canonical sources, {audit['frozenHashes']} frozen hashes across111 editions and {audit['original111EvidenceFiles']} original archive entries. "
validation='150 distinct Java methods covered;24 final affected checks pass after five initial107 compatibility failures retained in evidence.148 desktop checks and24 altered-evidence refusals pass. Actual74 exact child goals and58 workflow records archived;11 fresh completions, six required refusals, one abrupt recovery and32 retained procedures. Active64-goal limit unchanged;20 active children at final procedure capacity. Exact archived bytes and original source/outcome/publication checks verified. Actual History controls and screenshots; native workflow continuation while full24-task chat journal stays unchanged, prior121.319s chat-boundary and68.082s recorder-boundary trials retained; explicit old-runtime transition, no proof relabelling. Preserve private worlds and frozen editions; no delegation. '
for name,link in [('AGENTS.md','docs/PUBLICATION_111.json'),('README-CONTRIBUTORS.md','docs/PUBLICATION_111.json'),('docs/PROJECT_MEMORY.md','PUBLICATION_111.json'),('docs/DEVELOPMENT_LOG.md','PUBLICATION_111.json'),('docs/ARCHITECTURE.md','PUBLICATION_111.json')]:
 p=r/name;s=p.read_text(encoding='utf8');assert '## Edition111 â€” validated child-goal archival' in s;s=s.replace('## Edition111 â€” validated child-goal archival','## Edition111 â€” published and fetched back\n\n'+notice+validation+'[Publication receipt]('+link+').',1).replace('Publication pending actual push/fetch; CI separate.','Main/tag publication and fetched verification completed; remote CI is recorded separately.',1);p.write_text(s,encoding='utf8',newline='\n')
p=r/'README.md';p.write_text(p.read_text(encoding='utf8')+'\nPublished to main. [Edition111 fetched GitHub verification](docs/PUBLICATION_111.json).\n',encoding='utf8',newline='\n')
p=r/'docs/obsidian/119-completed-child-goal-archives.md';p.write_text(p.read_text(encoding='utf8').replace('Publication pending actual push/fetch; CI separate.','Publication and fetched verification completed; CI separate.')+'\n'+notice+validation+'[[docs/PUBLICATION_111.json|Publication receipt]]\n',encoding='utf8',newline='\n')
print(notice)
